use eventbus::EventDispatcher;
use std::cell::RefCell;
use std::rc::Rc;

#[test]
fn test_subscribe_and_dispatch() {
    let mut dispatcher = EventDispatcher::new();
    let received = Rc::new(RefCell::new(vec![]));
    let r = Rc::clone(&received);
    dispatcher.subscribe("click", move |data: &str| {
        r.borrow_mut().push(data.to_string());
    });
    dispatcher.dispatch("click", "button1");
    assert_eq!(*received.borrow(), vec!["button1"]);
}

#[test]
fn test_multiple_subscribers() {
    let mut dispatcher = EventDispatcher::new();
    let count = Rc::new(RefCell::new(0u32));
    let c1 = Rc::clone(&count);
    let c2 = Rc::clone(&count);
    dispatcher.subscribe("ping", move |_: &str| { *c1.borrow_mut() += 1; });
    dispatcher.subscribe("ping", move |_: &str| { *c2.borrow_mut() += 10; });
    dispatcher.dispatch("ping", "");
    assert_eq!(*count.borrow(), 11);
}

#[test]
fn test_different_events_isolated() {
    let mut dispatcher = EventDispatcher::new();
    let fired = Rc::new(RefCell::new(false));
    let f = Rc::clone(&fired);
    dispatcher.subscribe("a", move |_: &str| { *f.borrow_mut() = true; });
    dispatcher.dispatch("b", "irrelevant"); // should NOT fire handler for "a"
    assert!(!*fired.borrow());
}

#[test]
fn test_no_subscribers() {
    let mut dispatcher = EventDispatcher::new();
    // dispatching with no subscribers should not panic
    dispatcher.dispatch("unknown", "data");
}

#[test]
fn test_dispatch_data_passed() {
    let mut dispatcher = EventDispatcher::new();
    let last = Rc::new(RefCell::new(String::new()));
    let l = Rc::clone(&last);
    dispatcher.subscribe("msg", move |data: &str| {
        *l.borrow_mut() = data.to_string();
    });
    dispatcher.dispatch("msg", "hello");
    dispatcher.dispatch("msg", "world");
    assert_eq!(*last.borrow(), "world");
}

