Implement EventDispatcher in src/lib.rs.

use std::collections::HashMap;

pub struct EventDispatcher {
    handlers: HashMap<String, Vec<Box<dyn Fn(&str)>>>,
}

impl EventDispatcher {
    pub fn new() -> Self {
        EventDispatcher { handlers: HashMap::new() }
    }

    pub fn subscribe<F: Fn(&str) + 'static>(&mut self, event: &str, handler: F) {
        self.handlers
            .entry(event.to_string())
            .or_default()
            .push(Box::new(handler));
    }

    pub fn dispatch(&self, event: &str, data: &str) {
        if let Some(handlers) = self.handlers.get(event) {
            for handler in handlers {
                handler(data);
            }
        }
    }
}

